const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Articoli</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>L'articolo tedesco non sempre corrisponde al genere della parola in italiano. Per questo è meglio imparare i sostantivi insieme al loro articolo.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Esempi di articoli</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — tavolo</div>\n      <div class=\"kurss-example\">die Tür — porta</div>\n      <div class=\"kurss-example\">das Messer — coltello</div>\n      <div class=\"kurss-example\">das Mädchen — ragazza</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Spesso DER</h4>\n    <p class=\"artikuli-explain\">DER si usa spesso per persone di sesso maschile, giorni, mesi, stagioni e alcune parole con determinate desinenze.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regole</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → spesso DER, per esempio: der Computer, der Lehrer <span class=\"artikuli-note\">ma non sempre</span></div>\n      <div class=\"kurss-example\">-ling → spesso DER, per esempio: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → spesso DER, per esempio: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">persone di sesso maschile → der Mann, der Vater</div>\n      <div class=\"kurss-example\">professioni → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">marche di automobili → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">giorni → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">mesi → der August, der Dezember</div>\n      <div class=\"kurss-example\">stagioni → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Esempi</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — uomo</div>\n      <div class=\"kurss-example\">der Vater — padre</div>\n      <div class=\"kurss-example\">der Montag — lunedì</div>\n      <div class=\"kurss-example\">der August — agosto</div>\n      <div class=\"kurss-example\">der Sommer — estate</div>\n      <div class=\"kurss-example\">der Lehrer — insegnante</div>\n      <div class=\"kurss-example\">der Computer — computer</div>\n      <div class=\"kurss-example\">der Schmetterling — farfalla</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Spesso DIE</h4>\n    <p class=\"artikuli-explain\">DIE si usa spesso per persone di sesso femminile, per il plurale e per le parole con le desinenze -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regole</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">persone di sesso femminile → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">marche di motociclette → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">plurale → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">il plurale quasi sempre → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Esempi</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — donna</div>\n      <div class=\"kurss-example\">die Mutter — madre</div>\n      <div class=\"kurss-example\">die Wohnung — appartamento</div>\n      <div class=\"kurss-example\">die Rechnung — conto / fattura</div>\n      <div class=\"kurss-example\">die Freiheit — libertà</div>\n      <div class=\"kurss-example\">die Möglichkeit — possibilità</div>\n      <div class=\"kurss-example\">die Mannschaft — squadra</div>\n      <div class=\"kurss-example\">die Nation — nazione</div>\n      <div class=\"kurss-example\">die Universität — università</div>\n      <div class=\"kurss-example\">die Polizei — polizia</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Spesso DAS</h4>\n    <p class=\"artikuli-explain\">DAS si usa spesso per i diminutivi in -chen / -lein, per molte parole in -ment / -um e per i verbi usati come sostantivi.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regole</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metalli → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">elementi chimici → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">alberghi → das Hotel</div>\n      <div class=\"kurss-example\">colori usati come sostantivi → das Rot, das Blau</div>\n      <div class=\"kurss-example\">verbo usato come sostantivo → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">verbi usati come sostantivi → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Esempi</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — bambino</div>\n      <div class=\"kurss-example\">das Mädchen — ragazza</div>\n      <div class=\"kurss-example\">das Häuschen — casetta</div>\n      <div class=\"kurss-example\">das Instrument — strumento</div>\n      <div class=\"kurss-example\">das Zentrum — centro</div>\n      <div class=\"kurss-example\">das Museum — museo</div>\n      <div class=\"kurss-example\">das Essen — il mangiare / cibo</div>\n      <div class=\"kurss-example\">das Lernen — l'apprendimento</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Eccezioni importanti / da imparare con l'articolo</h4>\n    <p class=\"artikuli-explain\">Per alcune parole l'articolo non si può stabilire con certezza dalla desinenza o dal genere della parola in italiano. È meglio impararle insieme all'articolo.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — porta</div>\n      <div class=\"kurss-example\">das Messer — coltello</div>\n      <div class=\"kurss-example\">die Sonne — sole</div>\n      <div class=\"kurss-example\">der Mond — luna</div>\n      <div class=\"kurss-example\">das Mädchen — ragazza</div>\n      <div class=\"kurss-example\">das Auto — automobile</div>\n      <div class=\"kurss-example\">der Käse — formaggio</div>\n      <div class=\"kurss-example\">die Gabel — forchetta</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Le desinenze e i gruppi di parole aiutano a indovinare l'articolo, ma non sono una regola sicura al 100%. Se non sei sicuro, impara la parola insieme all'articolo.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Pronomi</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ e Dativ — le forme dei pronomi.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — chi?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — io</div><div class=\"kurss-example\">du — tu</div><div class=\"kurss-example\">er — lui</div><div class=\"kurss-example\">sie — lei</div><div class=\"kurss-example\">es — esso</div><div class=\"kurss-example\">wir — noi</div><div class=\"kurss-example\">ihr — voi</div><div class=\"kurss-example\">sie — loro</div><div class=\"kurss-example\">Sie — Lei (formale)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — chi? / che cosa?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — me / mi</div><div class=\"kurss-example\">dich — te / ti</div><div class=\"kurss-example\">ihn — lui / lo (m.)</div><div class=\"kurss-example\">sie — lei / la (f.)</div><div class=\"kurss-example\">es — esso / lo</div><div class=\"kurss-example\">uns — noi / ci</div><div class=\"kurss-example\">euch — voi / vi</div><div class=\"kurss-example\">sie — loro / li / le</div><div class=\"kurss-example\">Sie — Lei / La (formale)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — a chi?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — a me / mi</div><div class=\"kurss-example\">dir — a te / ti</div><div class=\"kurss-example\">ihm — a lui / gli</div><div class=\"kurss-example\">ihr — a lei / le</div><div class=\"kurss-example\">uns — a noi / ci</div><div class=\"kurss-example\">euch — a voi / vi</div><div class=\"kurss-example\">ihnen — a loro / gli</div><div class=\"kurss-example\">Ihnen — a Lei / Le (formale)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Come scegliere la forma?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — soggetto (chi compie l'azione?)</li><li><span class=\"case-red\">Akkusativ</span> — complemento oggetto (chi? / che cosa?)</li><li><span class=\"case-green\">Dativ</span> — complemento di termine (a chi?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Esempi</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Ti vedo.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Lo vedo.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Ci piacete.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Ti aiuto.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Gli do un libro.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Vi ringraziamo.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Il Nominativ è sempre il soggetto della frase, mentre Akkusativ e Dativ sono complementi. Guarda il verbo e chiedi: <span class=\"case-red\">chi? / che cosa?</span> o <span class=\"case-green\">a chi?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Vocali — lunghe e brevi</h3>\n            <p class=\"kurss-lesson-intro\">In tedesco le vocali possono essere lunghe o brevi. Questo influisce sulla pronuncia della parola.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vocale lunga</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — caldo</div><div class=\"kurss-example\">gut (gūt) — buono</div><div class=\"kurss-example\">Tat (tāt) — azione / fatto</div><div class=\"kurss-example\">Flur (flūr) — corridoio</div><div class=\"kurss-example\">Weg (vēk) — strada / cammino</div><div class=\"kurss-example\">Hut (hūt) — cappello</div><div class=\"kurss-example\">Hof (hōf) — cortile</div><div class=\"kurss-example\">Schlaf (shlāf) — sonno</div></div>\n              <p>Se dopo la vocale segue una sola consonante, la vocale si pronuncia spesso lunga.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vocale breve</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilz) — fungo</div><div class=\"kurss-example\">Wort (vort) — parola</div><div class=\"kurss-example\">Mund (munt) — bocca</div><div class=\"kurss-example\">bald (balt) — presto</div><div class=\"kurss-example\">scharf (sharf) — affilato / piccante</div><div class=\"kurss-example\">Feld (felt) — campo</div><div class=\"kurss-example\">voll (fol) — pieno</div></div>\n              <p>Se dopo la vocale seguono due o più consonanti, la vocale si pronuncia spesso breve.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Desinenze en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (singhen) — cantare</div><div class=\"kurss-example\">tragen (trāghen) — portare</div><div class=\"kurss-example\">Garten (garten) — giardino</div><div class=\"kurss-example\">Vogel (fōghel) — uccello</div><div class=\"kurss-example\">Segel (sēghel) — vela</div><div class=\"kurss-example\">Braten (brāten) — arrosto</div><div class=\"kurss-example\">Bogen (bōghen) — arco</div><div class=\"kurss-example\">Spiegel (shpīghel) — specchio</div><div class=\"kurss-example\">Finger (fingher) — dito</div><div class=\"kurss-example\">Halter (halter) — supporto / sostegno</div><div class=\"kurss-example\">Arbeiter (arbaiter) — operaio</div><div class=\"kurss-example\">Häuser (hoiser) — case</div><div class=\"kurss-example\">wieder (vīder) — di nuovo</div><div class=\"kurss-example\">breiter (braiter) — più largo</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>La lettera h come segno di vocale lunga</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (rāmen) — cornice / telaio</div><div class=\"kurss-example\">Ohr (ōr) — orecchio</div><div class=\"kurss-example\">Kohle (kōle) — carbone</div><div class=\"kurss-example\">Zahl (zāl) — numero</div><div class=\"kurss-example\">ihn (īn) — lo / lui</div><div class=\"kurss-example\">ihm (īm) — gli / a lui</div><div class=\"kurss-example\">Huhn (hūn) — gallina</div><div class=\"kurss-example\">nahm (nām) — prese / prendeva</div><div class=\"kurss-example\">nehmen (nēmen) — prendere</div><div class=\"kurss-example\">Schuh (shū) — scarpa</div></div>\n              <p>In alcune parole la h allunga la vocale precedente. In questi casi la h di solito non si pronuncia.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Desinenze con e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — lampada</div><div class=\"kurss-example\">Hase (hāse) — lepre</div><div class=\"kurss-example\">Knabe (knābe) — ragazzo</div><div class=\"kurss-example\">Rabe (rābe) — corvo</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>La i lunga = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (dī) — articolo «die»</div><div class=\"kurss-example\">diese (dīse) — questa / questi</div><div class=\"kurss-example\">wieder (vīder) — di nuovo</div><div class=\"kurss-example\">Fliege (flīghe) — mosca</div><div class=\"kurss-example\">Ziege (zīghe) — capra</div><div class=\"kurss-example\">Stiel (shtīl) — gambo / manico</div><div class=\"kurss-example\">Dieb (dīp) — ladro</div><div class=\"kurss-example\">hier (hīr) — qui</div></div>\n              <p>In tedesco la i lunga si scrive spesso ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vocali doppie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (sāl) — sala</div><div class=\"kurss-example\">Saat (sāt) — semina / semente</div><div class=\"kurss-example\">Staat (shtāt) — stato</div><div class=\"kurss-example\">Beere (bēre) — bacca</div><div class=\"kurss-example\">See (sē) — lago / mare</div><div class=\"kurss-example\">Beet (bēt) — aiuola</div><div class=\"kurss-example\">Boot (bōt) — barca</div><div class=\"kurss-example\">Moor (mōr) — palude / torbiera</div><div class=\"kurss-example\">Moos (mōs) — muschio</div></div>\n              <p>Le vocali doppie di solito si pronunciano lunghe.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — parete / muro</div><div class=\"kurss-example\">Wände (vende) — pareti / muri</div><div class=\"kurss-example\">Vater (fāter) — padre</div><div class=\"kurss-example\">Väter (fēter) — padri</div><div class=\"kurss-example\">Schrank (shrank) — armadio</div><div class=\"kurss-example\">Schränke (shrenke) — armadi</div><div class=\"kurss-example\">Bank (bank) — panchina / banca</div><div class=\"kurss-example\">Bänke (benke) — panchine</div><div class=\"kurss-example\">Tal (tāl) — valle</div><div class=\"kurss-example\">Täler (tēler) — valli</div></div>\n              <p>ä è la metafonia (Umlaut) di a.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rōse) — rosa</div><div class=\"kurss-example\">Röschen (rȫs-hen) — rosellina</div><div class=\"kurss-example\">Ofen (ōfen) — stufa / forno</div><div class=\"kurss-example\">Öfen (ȫfen) — stufe / forni</div><div class=\"kurss-example\">Rock (rok) — gonna</div><div class=\"kurss-example\">Röcke (röke) — gonne</div></div>\n              <p>ö è la metafonia (Umlaut) di o.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (kurz) — corto / breve</div><div class=\"kurss-example\">kürzer (kürzer) — più corto</div><div class=\"kurss-example\">Kunst (kunst) — arte</div><div class=\"kurss-example\">Künste (künste) — arti</div><div class=\"kurss-example\">Mutter (muter) — madre</div><div class=\"kurss-example\">Mütter (müter) — madri</div></div>\n              <p>ü è la metafonia (Umlaut) di u.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dittonghi: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) — albero</div><div class=\"kurss-example\">Bäume (boime) — alberi</div><div class=\"kurss-example\">Haus (haus) — casa</div><div class=\"kurss-example\">Häuser (hoiser) — case</div><div class=\"kurss-example\">Strauch (shtrauh) — arbusto / cespuglio</div><div class=\"kurss-example\">Sträucher (shtroiher) — arbusti / cespugli</div><div class=\"kurss-example\">Maus (maus) — topo</div><div class=\"kurss-example\">Mäuse (moise) — topi</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dittonghi: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (hoite) — oggi</div><div class=\"kurss-example\">Leute (loite) — gente / persone</div><div class=\"kurss-example\">neu (noi) — nuovo</div><div class=\"kurss-example\">neun (noin) — nove</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dittonghi: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (main) — mio</div><div class=\"kurss-example\">dein (dain) — tuo</div><div class=\"kurss-example\">sein (sain) — suo / sua / essere</div><div class=\"kurss-example\">frei (frai) — libero</div><div class=\"kurss-example\">arbeiten (arbaiten) — lavorare</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Note di pronuncia della lezione 2</h4>\n              <ul class=\"kurss-summary-list\"><li>nelle parole ich, nicht, rechnen, zeichnen «ch» si pronuncia dolce</li><li>nelle parole arbeiten e zeichnen «ei» si pronuncia come «ai»</li><li>«sp» a inizio parola si pronuncia come «shp» (con la «sc» di «scena»)</li><li>nel verbo tun la lettera «u» si pronuncia lunga</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Riepilogo</h4>\n              <ul class=\"kurss-summary-list\"><li>una sola consonante dopo la vocale → spesso vocale lunga</li><li>due o più consonanti → spesso vocale breve</li><li>la h può allungare la vocale</li><li>ie indica spesso la i lunga</li><li>le vocali doppie di solito sono lunghe</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Consonanti e combinazioni di lettere</h3>\n            <p class=\"kurss-lesson-intro\">In tedesco alcune consonanti e combinazioni di lettere si pronunciano diversamente da come si scrivono. In questa lezione ci sono gli esempi più importanti per chi inizia.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Consonanti</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (rāt) — ruota</div><div class=\"kurss-example\">die Räder (rēder) — ruote</div><div class=\"kurss-example\">Bad (bāt) — bagno</div><div class=\"kurss-example\">Bäder (bēder) — bagni</div></div>\n              <p>A fine parola le consonanti spesso non si pronunciano come si scrivono.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>«ch» può essere pronunciato in modo dolce o duro. In alcune parole suona come una «h» aspirata (un soffio, suono che in italiano non esiste), in altre più vicino a «k».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (rehnen) — calcolare</div><div class=\"kurss-example\">zeichnen (zaihnen) — disegnare</div><div class=\"kurss-example\">nicht (niht) — non</div><div class=\"kurss-example\">schlecht (shleht) — cattivo / brutto</div><div class=\"kurss-example\">mich (mih) — mi / me</div><div class=\"kurss-example\">dich (dih) — ti / te</div><div class=\"kurss-example\">Strauch (shtrauh) — arbusto / cespuglio</div><div class=\"kurss-example\">noch (noh) — ancora</div><div class=\"kurss-example\">Nacht (naht) — notte</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>In tedesco «sch» si pronuncia come «sc» in «scena» (qui trascritto «sh»).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (shūle) — scuola</div><div class=\"kurss-example\">Schüler (shǖler) — alunno / scolaro</div><div class=\"kurss-example\">Schiff (shif) — nave</div><div class=\"kurss-example\">Schraube (shraube) — vite</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp e st a inizio parola</h4>\n              <p>All'inizio di parola o di sillaba «sp» si pronuncia spesso come «shp» e «st» come «sht» (con la «sc» di «scena»).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (shpīlen) — giocare / suonare</div><div class=\"kurss-example\">Sprung (shprung) — salto</div><div class=\"kurss-example\">stehen (shtēen) — stare in piedi</div><div class=\"kurss-example\">Stall (shtal) — stalla</div><div class=\"kurss-example\">Stand (shtant) — posizione / stato / bancarella</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>In tedesco «qu» si pronuncia di solito come «kv» (non come la «qu» italiana).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvāl) — tormento</div><div class=\"kurss-example\">Quartier (kvartīr) — alloggio / quartiere</div><div class=\"kurss-example\">quer (kvēr) — di traverso</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s e z</h4>\n              <p>All'inizio di parola «s» suona spesso sonora, come la «s» di «rosa» o di «sbaglio». La lettera «z» in tedesco si pronuncia «ts», come la «z» di «pizza».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (sāghen) — dire</div><div class=\"kurss-example\">singen (singhen) — cantare</div><div class=\"kurss-example\">Rose (rōse) — rosa</div><div class=\"kurss-example\">Zahl (zāl) — numero</div><div class=\"kurss-example\">Zeit (zait) — tempo</div><div class=\"kurss-example\">Zink (zink) — zinco</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>In tedesco «v» si pronuncia spesso come «f». Nelle parole straniere spesso suona come la «v» italiana.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fāter) — padre</div><div class=\"kurss-example\">von (fon) — da / di</div><div class=\"kurss-example\">viel (fīl) — molto</div><div class=\"kurss-example\">vier (fīr) — quattro</div><div class=\"kurss-example\">Villa (villa) — villa</div><div class=\"kurss-example\">Klavier (klavīr) — pianoforte</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x e y</h4>\n              <p>«x» si pronuncia «ks». In alcune parole «y» si pronuncia come «ü».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (fēliks) — Felix / Felice</div><div class=\"kurss-example\">Axt (akst) — ascia</div><div class=\"kurss-example\">Mystik (müstik) — mistica / misticismo</div><div class=\"kurss-example\">Mythe (mǖte) — mito</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>In tedesco «ß» si pronuncia come una «s» sorda, come in «sole».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (fūs) — piede</div><div class=\"kurss-example\">Füße (fǖse) — piedi</div><div class=\"kurss-example\">Grüße (grǖse) — saluti</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Riepilogo</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → sh (come «sc» in «scena»)</li><li>sp / st all'inizio → shp / sht</li><li>qu → kv</li><li>z → ts (come in «pizza»)</li><li>v spesso → f</li><li>x → ks</li><li>ß → s sorda</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Le basi dei verbi</h3>\n            <p class=\"kurss-lesson-intro\">Verbi della lezione 1 e le loro forme (coniugazione)</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Verbi</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — venire</div><div class=\"kurss-example\">gehen — andare</div><div class=\"kurss-example\">stehen — stare in piedi</div><div class=\"kurss-example\">singen — cantare</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — io vengo</div><div class=\"kurss-example\">du kommst — tu vieni</div><div class=\"kurss-example\">er kommt — lui viene</div><div class=\"kurss-example\">sie kommt — lei viene</div><div class=\"kurss-example\">wir kommen — noi veniamo</div><div class=\"kurss-example\">ihr kommt — voi venite</div><div class=\"kurss-example\">sie kommen — loro vengono</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — io vado</div><div class=\"kurss-example\">du gehst — tu vai</div><div class=\"kurss-example\">er geht — lui va</div><div class=\"kurss-example\">sie geht — lei va</div><div class=\"kurss-example\">wir gehen — noi andiamo</div><div class=\"kurss-example\">ihr geht — voi andate</div><div class=\"kurss-example\">sie gehen — loro vanno</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — io sto in piedi</div><div class=\"kurss-example\">du stehst — tu stai in piedi</div><div class=\"kurss-example\">er steht — lui sta in piedi</div><div class=\"kurss-example\">sie steht — lei sta in piedi</div><div class=\"kurss-example\">wir stehen — noi stiamo in piedi</div><div class=\"kurss-example\">ihr steht — voi state in piedi</div><div class=\"kurss-example\">sie stehen — loro stanno in piedi</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — io canto</div><div class=\"kurss-example\">du singst — tu canti</div><div class=\"kurss-example\">er singt — lui canta</div><div class=\"kurss-example\">sie singt — lei canta</div><div class=\"kurss-example\">wir singen — noi cantiamo</div><div class=\"kurss-example\">ihr singt — voi cantate</div><div class=\"kurss-example\">sie singen — loro cantano</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Verbi della lezione 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — giocare</div><div class=\"kurss-example\">arbeiten — lavorare</div><div class=\"kurss-example\">fragen — chiedere</div><div class=\"kurss-example\">antworten — rispondere</div><div class=\"kurss-example\">rechnen — calcolare</div><div class=\"kurss-example\">zeichnen — disegnare</div><div class=\"kurss-example\">tun — fare</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — io gioco</div><div class=\"kurss-example\">du spielst — tu giochi</div><div class=\"kurss-example\">er spielt — lui gioca</div><div class=\"kurss-example\">sie spielt — lei gioca</div><div class=\"kurss-example\">wir spielen — noi giochiamo</div><div class=\"kurss-example\">ihr spielt — voi giocate</div><div class=\"kurss-example\">sie spielen — loro giocano</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — io lavoro</div><div class=\"kurss-example\">du arbeitest — tu lavori</div><div class=\"kurss-example\">er arbeitet — lui lavora</div><div class=\"kurss-example\">sie arbeitet — lei lavora</div><div class=\"kurss-example\">wir arbeiten — noi lavoriamo</div><div class=\"kurss-example\">ihr arbeitet — voi lavorate</div><div class=\"kurss-example\">sie arbeiten — loro lavorano</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — io chiedo</div><div class=\"kurss-example\">du fragst — tu chiedi</div><div class=\"kurss-example\">er fragt — lui chiede</div><div class=\"kurss-example\">sie fragt — lei chiede</div><div class=\"kurss-example\">wir fragen — noi chiediamo</div><div class=\"kurss-example\">ihr fragt — voi chiedete</div><div class=\"kurss-example\">sie fragen — loro chiedono</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — io rispondo</div><div class=\"kurss-example\">du antwortest — tu rispondi</div><div class=\"kurss-example\">er antwortet — lui risponde</div><div class=\"kurss-example\">sie antwortet — lei risponde</div><div class=\"kurss-example\">wir antworten — noi rispondiamo</div><div class=\"kurss-example\">ihr antwortet — voi rispondete</div><div class=\"kurss-example\">sie antworten — loro rispondono</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — io calcolo</div><div class=\"kurss-example\">du rechnest — tu calcoli</div><div class=\"kurss-example\">er rechnet — lui calcola</div><div class=\"kurss-example\">sie rechnet — lei calcola</div><div class=\"kurss-example\">wir rechnen — noi calcoliamo</div><div class=\"kurss-example\">ihr rechnet — voi calcolate</div><div class=\"kurss-example\">sie rechnen — loro calcolano</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — io disegno</div><div class=\"kurss-example\">du zeichnest — tu disegni</div><div class=\"kurss-example\">er zeichnet — lui disegna</div><div class=\"kurss-example\">sie zeichnet — lei disegna</div><div class=\"kurss-example\">wir zeichnen — noi disegniamo</div><div class=\"kurss-example\">ihr zeichnet — voi disegnate</div><div class=\"kurss-example\">sie zeichnen — loro disegnano</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — io faccio</div><div class=\"kurss-example\">du tust — tu fai</div><div class=\"kurss-example\">er tut — lui fa</div><div class=\"kurss-example\">sie tut — lei fa</div><div class=\"kurss-example\">wir tun — noi facciamo</div><div class=\"kurss-example\">ihr tut — voi fate</div><div class=\"kurss-example\">sie tun — loro fanno</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Struttura della frase</h3>\n            <p class=\"kurss-lesson-intro\">Nelle frasi interrogative in tedesco il verbo di solito sta al primo posto.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Esempi</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Tu vieni.</div><div class=\"kurss-example\">Kommst du? — Vieni?</div><div class=\"kurss-example\">Er singt. — Lui canta.</div><div class=\"kurss-example\">Singt er? — Canta lui?</div><div class=\"kurss-example\">Stehst du? — Stai in piedi?</div><div class=\"kurss-example\">Ja, ich stehe. — Sì, sto in piedi.</div><div class=\"kurss-example\">Geht ihr? — Andate?</div><div class=\"kurss-example\">Ja, wir gehen. — Sì, andiamo.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Domande con «was»</h4>\n              <p>Se la domanda inizia con una parola interrogativa, in tedesco il verbo di solito sta subito dopo la parola interrogativa.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Che cosa fai?</div><div class=\"kurss-example\">Was tut er? — Che cosa fa lui?</div><div class=\"kurss-example\">Was tut sie? — Che cosa fa lei?</div><div class=\"kurss-example\">Was tun sie? — Che cosa fanno loro?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Negazione con «nicht»</h4>\n              <p>Se la negazione «nicht» si riferisce al verbo, in tedesco di solito sta dopo il verbo.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Non gioco.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul non chiede.</div><div class=\"kurss-example\">Er kommt nicht. — Lui non viene.</div><div class=\"kurss-example\">Sie singen nicht. — Loro non cantano.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Frasi della lezione 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Giochi?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — No, non gioco, lavoro.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul non chiede, lavora.</div><div class=\"kurss-example\">Arbeitest du? — Lavori?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — No, non lavoro, canto.</div><div class=\"kurss-example\">Was tut Paul? — Che cosa fa Paul?</div><div class=\"kurss-example\">Er spielt. — Lui gioca.</div><div class=\"kurss-example\">Was tut Marie? — Che cosa fa Marie?</div><div class=\"kurss-example\">Sie singt. — Lei canta.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul gioca, ma Marie canta.</div><div class=\"kurss-example\">Singt ihr? — Cantate?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — No, non cantiamo, lavoriamo.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Che cosa fanno Paul e Marie?</div><div class=\"kurss-example\">Sie fragen. — Loro chiedono.</div><div class=\"kurss-example\">Sie antworten nicht. — Loro non rispondono.</div><div class=\"kurss-example\">Wer arbeitet? — Chi lavora?</div><div class=\"kurss-example\">Wir arbeiten. — Noi lavoriamo.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Noi calcoliamo e disegniamo.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Loro vengono, chiedono, rispondono, lavorano, giocano, cantano e vanno.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Lezione 2</h3>\n            <p class=\"kurss-lesson-intro\">Seconda lezione: dialoghi, parole, pronuncia, grammatica e traduzione.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoghi / frasi</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Parole</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — giocare; suonare</div>\n                  <div class=\"kurss-example\">nein — no</div>\n                  <div class=\"kurss-example\">nicht — non</div>\n                  <div class=\"kurss-example\">arbeiten — lavorare</div>\n                  <div class=\"kurss-example\">fragen — chiedere</div>\n                  <div class=\"kurss-example\">was tut er? — che cosa fa lui?</div>\n                  <div class=\"kurss-example\">was tun sie? — che cosa fanno loro?</div>\n                  <div class=\"kurss-example\">aber — ma</div>\n                  <div class=\"kurss-example\">antworten — rispondere</div>\n                  <div class=\"kurss-example\">rechnen — calcolare</div>\n                  <div class=\"kurss-example\">zeichnen — disegnare</div>\n                  <div class=\"kurss-example\">Marie — Maria</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronuncia</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nelle parole ich, nicht, rechnen, zeichnen il suono ch si pronuncia dolce: in italiano non esiste, somiglia a una h fortemente soffiata con la lingua nella posizione della i, quasi una «sci» sussurrata.</div><div class=\"kurss-example\">Nelle parole arbeiten, zeichnen il dittongo ei si pronuncia all'incirca come «ai» nella parola italiana «mai».</div><div class=\"kurss-example\">Il gruppo consonantico sp si pronuncia come shp: spielen (shpiilen).</div><div class=\"kurss-example\">Nel verbo tun la u si pronuncia lunga in tutte le persone.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Desinenze con e</h4>\n                  <div class=\"lesson1-grammar-note\">Se la radice del verbo termina in t, d, chn, nella coniugazione si inserisce una e davanti alle desinenze -st e -t.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>La parola interrogativa</h4>\n                  <div class=\"lesson1-grammar-note\">Nelle frasi interrogative che iniziano con una parola interrogativa, per esempio: che cosa? chi? quale? perché? per quale motivo? ecc., il verbo si trova subito dopo la parola interrogativa.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Che cosa fai?</div><div class=\"kurss-example\">Was tut er? — Che cosa fa lui?</div><div class=\"kurss-example\">Was tut sie? — Che cosa fa lei?</div><div class=\"kurss-example\">Was tun sie? — Che cosa fanno loro?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>La negazione con nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Se la negazione nicht si riferisce al verbo, la parola che nega si trova dopo il verbo.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Lui non viene.</div><div class=\"kurss-example\">Sie singen nicht. — Loro non cantano.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduci</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lezione 2: scheda di traduzione\">\n                    <span class=\"lesson1-training-progress\">Lezione 2 · Traduci: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Chi chiede?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Clicca sulla scheda per vedere la traduzione tedesca. Dopo la risposta, il clic successivo mostra la scheda seguente.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Lezione 6</h3>\n    <p class=\"kurss-lesson-intro\">Numeri, plurale, umlaut e forme plurali dei sostantivi.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoghi / frasi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Parole</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — si trova, c'è, giace</div><div class=\"kurss-example\">der Bleistift (blaishtift) — la matita</div><div class=\"kurss-example\">einige (ainighe) — alcuni</div><div class=\"kurss-example\">hinlegen — posare, mettere giù</div><div class=\"kurss-example\">legt hin — posa</div><div class=\"kurss-example\">wieder (viider) — di nuovo</div><div class=\"kurss-example\">aufmachen — aprire</div><div class=\"kurss-example\">er macht auf — lui apre</div><div class=\"kurss-example\">anspitzen (anshpitsen) — temperare</div><div class=\"kurss-example\">er spitzt an — lui tempera</div><div class=\"kurss-example\">sich setzen — sedersi</div><div class=\"kurss-example\">setzt sich — si siede</div><div class=\"kurss-example\">der Schlüssel (shlüssel) — la chiave</div><div class=\"kurss-example\">das Fenster (fenster) — la finestra</div><div class=\"kurss-example\">die Tafel (dii taafel) — la lavagna</div><div class=\"kurss-example\">der Garten — il giardino</div><div class=\"kurss-example\">der Löffel — il cucchiaio</div><div class=\"kurss-example\">zählen (tseelen) — contare</div><div class=\"kurss-example\">die Nadel — l'ago</div><div class=\"kurss-example\">was ist das — che cos'è?</div><div class=\"kurss-example\">der Hammer — il martello</div><div class=\"kurss-example\">die Hämmer — i martelli</div><div class=\"kurss-example\">der Deckel (deer dekkel) — il coperchio</div><div class=\"kurss-example\">der Teller — il piatto</div><div class=\"kurss-example\">der Wagen — il carro</div><div class=\"kurss-example\">der Schlitten — la slitta</div><div class=\"kurss-example\">das Ding — la cosa</div><div class=\"kurss-example\">die Dinge — le cose</div><div class=\"kurss-example\">wie sind die Dinge? — come sono le cose?</div><div class=\"kurss-example\">voll (foll) — pieno</div><div class=\"kurss-example\">leer (leer) — vuoto</div><div class=\"kurss-example\">schwer (shveer) — pesante, difficile</div><div class=\"kurss-example\">leicht — leggero</div><div class=\"kurss-example\">der Eimer — il secchio</div><div class=\"kurss-example\">wieviel (viifiil) — quanto, quanti</div><div class=\"kurss-example\">wieviel Nadeln — quanti aghi</div><div class=\"kurss-example\">hier (hiir) — qui</div><div class=\"kurss-example\">dort — là</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronuncia</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä è l'umlaut della vocale a e si pronuncia come una e, breve o lunga.</div><div class=\"kurss-example\">Esempi: das Mädchen (meet-hen), die Bänke (dii benke), der Vater (deer faater), die Väter (dii feeter).</div><div class=\"kurss-example\">ü è l'umlaut della vocale u. Per pronunciarla bisogna arrotondare molto le labbra e, tenendole arrotondate, cercare di dire i.</div><div class=\"kurss-example\">Esempi: fünf, der Schlüssel (shlüssel).</div><div class=\"kurss-example\">ö si pronuncia con le labbra arrotondate, cercando di dire e: der Löffel.</div><div class=\"kurss-example\">Una vocale doppia indica una vocale lunga: leer (leer).</div><div class=\"kurss-example\">Il dittongo eu si pronuncia oi: neun (noin).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Grammatica e spiegazioni</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nei verbi composti il prefisso accentato, al presente, si separa dal verbo e va alla fine della frase.</div><div class=\"kurss-example\">Esempi: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Il numerale «uno», usato con un sostantivo, ha una forma per ciascuno dei tre generi: al maschile ein, al femminile eine, al neutro ein.</div><div class=\"kurss-example\">Esempi: ein Schüler — un alunno; eine Schülerin — un'alunna; ein Kind — un bambino.</div><div class=\"kurss-example\">Numeri: eins, zwei, drei, vier (fiir), fünf, sechs (seks), sieben (siiben), acht, neun (noin), zehn (tseen).</div><div class=\"kurss-example\">In tedesco la copula ha una forma singolare e una plurale: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">In italiano il pronome dimostrativo cambia per genere e numero, mentre in tedesco si usa una sola forma: das.</div><div class=\"kurss-example\">Esempi: questo è un martello — das ist ein Hammer; questo è un ago — das ist eine Nadel; questi sono martelli — das sind Hämmer; questi sono aghi — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — il carro e der Schlitten — la slitta: in tedesco, come in italiano, si usano sia al singolare sia al plurale.</div><div class=\"kurss-example\">I sostantivi maschili e neutri con la desinenza -er, -el, -en spesso al plurale non prendono alcuna desinenza.</div><div class=\"kurss-example\">Esempi: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">I sostantivi femminili con la desinenza -el, -er al plurale prendono -n.</div><div class=\"kurss-example\">Esempi: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Eccezioni: die Mutter (madre) — die Mütter (madri); die Tochter (figlia) — die Töchter (figlie).</div><div class=\"kurss-example\">L'articolo indeterminativo non ha il plurale: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Nella frase enunciativa il predicato verbale occupa il secondo posto: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduci</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lezione 6: scheda di traduzione\"><span class=\"lesson1-training-progress\">Lezione 6 · Traduci: 1 / 21</span><span class=\"lesson1-training-text\">Paul prende una matita e disegna.</span></button><p class=\"lesson1-training-hint\">Clicca sulla scheda per vedere la traduzione tedesca. Dopo la risposta, il clic successivo mostra la scheda seguente.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Lezione 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, accusativo, sitzen, fragen e la desinenza -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoghi / frasi</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Parole</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (sitsen) — stare seduto</div>\n        <div class=\"kurss-example\">fragen (fraaghen) — chiedere, domandare</div>\n        <div class=\"kurss-example\">der Lehrer (deer leerer) — il maestro, l'insegnante</div>\n        <div class=\"kurss-example\">gut (guut) — bene</div>\n        <div class=\"kurss-example\">wen (veen) — chi (complemento oggetto)</div>\n        <div class=\"kurss-example\">loben — lodare</div>\n        <div class=\"kurss-example\">der Schüler (shüüler) — l'alunno</div>\n        <div class=\"kurss-example\">klein — piccolo</div>\n        <div class=\"kurss-example\">groß (groos) — grande</div>\n        <div class=\"kurss-example\">die Lehrerin — la maestra, l'insegnante</div>\n        <div class=\"kurss-example\">die Schülerin — l'alunna</div>\n        <div class=\"kurss-example\">schlecht (shleht) — male</div>\n        <div class=\"kurss-example\">tadeln — rimproverare</div>\n        <div class=\"kurss-example\">oder (ooder) — o, oppure</div>\n        <div class=\"kurss-example\">das Kind (kint) — il bambino</div>\n        <div class=\"kurss-example\">artig (aartih) — bravo, ubbidiente</div>\n        <div class=\"kurss-example\">die Mutter — la madre</div>\n        <div class=\"kurss-example\">lieben (liiben) — amare</div>\n        <div class=\"kurss-example\">der Vater (faater) — il padre</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronuncia</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz è una z raddoppiata e si pronuncia come la z italiana di «pizza»: sitzen (sitsen).</div>\n        <div class=\"kurss-example\">Nelle parole tedesche la v si pronuncia come f: der Vater (faater).</div>\n        <div class=\"kurss-example\">ß si chiama Eszett e si pronuncia come la s italiana di «sole»: groß (groos), weiß (vais).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativo e accusativo</h4><div class=\"lesson1-grammar-note\">In italiano il soggetto e il complemento oggetto rispondono entrambi alla domanda chi? / che cosa?, senza distinzione di forma.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In tedesco, al nominativo, la domanda è wer? per le persone e was? per le cose.</div><div class=\"kurss-example\">All'accusativo la domanda è wen? per le persone e was? per le cose.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Il cambiamento dell'articolo all'accusativo</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + accusativo</h4><div class=\"lesson1-grammar-note\">In tedesco il verbo fragen regge l'accusativo.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">La desinenza -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Molti sostantivi femminili si formano con la desinenza -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">La posizione del verbo</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nella frase enunciativa il verbo occupa il secondo posto.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduci</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lezione 5: scheda di traduzione\"><span class=\"lesson1-training-progress\">Lezione 5 · Traduci: 1 / 16</span><span class=\"lesson1-training-text\">Il padre chi ama?</span></button><p class=\"lesson1-training-hint\">Clicca sulla scheda per vedere la traduzione tedesca. Dopo la risposta, il clic successivo mostra la scheda seguente.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Lezione 4</h3>\n            <p class=\"kurss-lesson-intro\">Accusativo, nehmen, hinlegen, hinausgehen e aggettivi.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoghi / frasi</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Parole</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (neemen) — prendere</div><div class=\"kurss-example\">er nimmt (nimt) — lui prende</div><div class=\"kurss-example\">der Federhalter (deer feederhalter) — il portapenne</div><div class=\"kurss-example\">einen Federhalter — un portapenne</div><div class=\"kurss-example\">zeigen — mostrare</div><div class=\"kurss-example\">schwarz (shvarts) — nero</div><div class=\"kurss-example\">weiß (vais) — bianco</div><div class=\"kurss-example\">die Feder (dii feeder) — il pennino</div><div class=\"kurss-example\">eine Feder — un pennino</div><div class=\"kurss-example\">spitz (shpits) — appuntito</div><div class=\"kurss-example\">hinlegen — posare, mettere giù</div><div class=\"kurss-example\">legt hin — posa</div><div class=\"kurss-example\">das Mädchen (meet-hen) — la ragazza</div><div class=\"kurss-example\">das Messer — il coltello</div><div class=\"kurss-example\">ein Messer — un coltello</div><div class=\"kurss-example\">scharf — affilato</div><div class=\"kurss-example\">stumpf (shtumpf) — smussato, non affilato</div><div class=\"kurss-example\">dann — poi, allora</div><div class=\"kurss-example\">hinaus — fuori</div><div class=\"kurss-example\">hinausgehen — uscire, andare fuori</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronuncia</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Le desinenze -en, -er, -el sono atone, perciò la e in queste desinenze si sente appena: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">In tedesco la h può essere sia un suono sia un segno di allungamento della vocale precedente.</div><div class=\"kurss-example\">Se la h indica l'allungamento, non si pronuncia: nehmen (neemen).</div><div class=\"kurss-example\">Se una vocale è seguita da una sola consonante, si pronuncia lunga: die (dii) Feder (feeder), den (deen).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>L'accusativo</h4><div class=\"lesson1-grammar-note\">Al femminile e al neutro l'accusativo è uguale al nominativo. Cambia solo il maschile.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>I pronomi</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — maschile</div><div class=\"kurss-example\">sie — femminile</div><div class=\"kurss-example\">es — neutro</div><div class=\"kurss-example\">al plurale — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>I verbi separabili</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Gli aggettivi</h4><div class=\"lesson1-grammar-note\">Se nella frase l'aggettivo è predicato, non cambia né per genere né per numero.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>La negazione con nicht</h4><div class=\"lesson1-grammar-note\">Se nicht nega un aggettivo, si trova davanti alla parola negata.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">I sostantivi con la desinenza -chen e -lein sono neutri: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduci</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lezione 4: scheda di traduzione\"><span class=\"lesson1-training-progress\">Lezione 4 · Traduci: 1 / 16</span><span class=\"lesson1-training-text\">La ragazza prende un portapenne.</span></button><p class=\"lesson1-training-hint\">Clicca sulla scheda per vedere la traduzione tedesca. Dopo la risposta, il clic successivo mostra la scheda seguente.</p></div></div></details>",
  "kurssLesson3": "            <h3>Lezione 3</h3>\n            <p class=\"kurss-lesson-intro\">Terza lezione: dialoghi, parole, pronuncia, grammatica e traduzione.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoghi / frasi</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Parole</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — chi</div><div class=\"kurss-example\">was — che cosa</div><div class=\"kurss-example\">hier — qui</div><div class=\"kurss-example\">dort — là</div><div class=\"kurss-example\">der Tisch — il tavolo</div><div class=\"kurss-example\">ein Tisch — un tavolo</div><div class=\"kurss-example\">die Bank — la panca</div><div class=\"kurss-example\">eine Bank — una panca</div><div class=\"kurss-example\">liegen — stare disteso, giacere</div><div class=\"kurss-example\">liegt hier ein Buch? — c'è / si trova un libro qui?</div><div class=\"kurss-example\">das Buch — il libro</div><div class=\"kurss-example\">ein Buch — un libro</div><div class=\"kurss-example\">hängen — essere appeso</div><div class=\"kurss-example\">das Bild — il quadro</div><div class=\"kurss-example\">ein Bild — un quadro</div><div class=\"kurss-example\">die Tafel — la lavagna</div><div class=\"kurss-example\">eine Tafel — una lavagna</div><div class=\"kurss-example\">wie — come</div><div class=\"kurss-example\">ist — è</div><div class=\"kurss-example\">dick — spesso, grosso</div><div class=\"kurss-example\">das Heft — il quaderno</div><div class=\"kurss-example\">ein Heft — un quaderno</div><div class=\"kurss-example\">dünn — sottile, magro</div><div class=\"kurss-example\">niedrig — basso</div><div class=\"kurss-example\">hoch — alto</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronuncia</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In tedesco la i lunga si scrive ie: liegen (liighen), hier (hiir), wie (vii).</div><div class=\"kurss-example\">ck è una k doppia: dick (dikk).</div><div class=\"kurss-example\">Negli aggettivi e negli avverbi la desinenza -ig suona come un leggero -ich: niedrig (niidrih).</div><div class=\"kurss-example\">Se alla desinenza -ig segue una e, cioè -ige, la g si pronuncia come una g dura: niedrige (niidrighe) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Il soggetto</h4><div class=\"lesson1-grammar-note\">In tedesco il soggetto risponde alla domanda wer? / was? ed è al nominativo.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Con wer? si chiede di persone.</div><div class=\"kurss-example\">Con was? si chiede di cose.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Gli articoli</h4><div class=\"lesson1-grammar-note\">In tedesco i sostantivi hanno 3 generi: maschile, femminile e neutro. Davanti ai sostantivi di solito c'è una parolina chiamata articolo. Il suo genere non sempre corrisponde a quello italiano.</div><h5 class=\"lesson2-subtitle\">L'articolo determinativo</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">maschile — der</div><div class=\"kurss-example\">femminile — die</div><div class=\"kurss-example\">neutro — das</div><div class=\"kurss-example\">Al plurale l'articolo determinativo è die per tutti e tre i generi.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">L'articolo indeterminativo</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">maschile — ein</div><div class=\"kurss-example\">femminile — eine</div><div class=\"kurss-example\">neutro — ein</div><div class=\"kurss-example\">L'articolo indeterminativo non ha il plurale.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Nomi propri</h4><div class=\"lesson1-grammar-note\">Davanti ai nomi propri non si usa l'articolo.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>La posizione del verbo</h4><div class=\"lesson1-grammar-note\">Nella frase enunciativa il verbo occupa il secondo posto.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In tedesco, degli oggetti in posizione verticale si dice che stanno in piedi:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Degli oggetti in posizione orizzontale si dice che giacciono:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Gli oggetti possono anche essere appesi:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduci</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lezione 3: scheda di traduzione\"><span class=\"lesson1-training-progress\">Lezione 3 · Traduci: 1 / 22</span><span class=\"lesson1-training-text\">Calcoli?</span></button><p class=\"lesson1-training-hint\">Clicca sulla scheda per vedere la traduzione tedesca. Dopo la risposta, il clic successivo mostra la scheda seguente.</p></div></div></details>",
  "kurssLesson7": "            <h3>Lezione 7</h3>\n            <p class=\"kurss-lesson-intro\">Settima lezione: imperativo, forma di cortesia e plurale.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoghi / frasi</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Parole</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — cantare</div><div class=\"kurss-example\">singe — canta</div><div class=\"kurss-example\">singt — cantate</div><div class=\"kurss-example\">singen Sie — canti (forma di cortesia)</div><div class=\"kurss-example\">das Lied (das liit) — la canzone</div><div class=\"kurss-example\">Sie — Lei</div><div class=\"kurss-example\">zählen — contare</div><div class=\"kurss-example\">das Fräulein (froilain) — la signorina</div><div class=\"kurss-example\">der Müller — il mugnaio</div><div class=\"kurss-example\">öffnen — aprire</div><div class=\"kurss-example\">das Fenster (fenster) — la finestra</div><div class=\"kurss-example\">alle — tutti</div><div class=\"kurss-example\">der Spiegel (shpiighel) — lo specchio</div><div class=\"kurss-example\">der Lappen — lo straccio, il panno</div><div class=\"kurss-example\">der Spaten — la vanga</div><div class=\"kurss-example\">der Besen — la scopa</div><div class=\"kurss-example\">die Schaufel — la paletta</div><div class=\"kurss-example\">die Schüssel — la ciotola, la scodella</div><div class=\"kurss-example\">das Zimmer — la stanza</div><div class=\"kurss-example\">das Ufer (uufer) — la riva</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronuncia</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp all'inizio di parola o di sillaba si pronuncia shp: der Spiegel (deer shpiighel).</div><div class=\"kurss-example\">sch si pronuncia come «sc» nella parola italiana «scena»: die Schaufel (dii shaufel), die Schüssel (dii shüssel).</div><div class=\"kurss-example\">Il dittongo äu si pronuncia come «oi» nella parola italiana «poi»: das Fräulein (das froilain).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>L'imperativo</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">L'imperativo alla 2ª persona singolare corrisponde alla 2ª persona singolare del verbo senza la desinenza personale -st, con l'aggiunta della desinenza -e.</div><div class=\"kurss-example\">Esempi: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Molto spesso la desinenza -e non si usa, se senza di essa l'imperativo è monosillabico: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>L'imperativo plurale</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">L'imperativo alla 2ª persona plurale è uguale alla 2ª persona plurale del presente, ma si usa senza pronome.</div><div class=\"kurss-example\">Esempi: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>La forma di cortesia con Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">La forma di cortesia «Lei» in tedesco corrisponde alla 3ª persona plurale. Il pronome Sie si scrive con la maiuscola e si mette dopo il verbo.</div><div class=\"kurss-example\">Esempi: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nel verbo öffnen, per facilitare la pronuncia, alla 2ª e 3ª persona singolare e alla 2ª persona plurale si inserisce una e tra la radice e la desinenza: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Esercizio</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lezione 7: scheda di esercizio\"><span class=\"lesson1-training-progress\">Lezione 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — chiedere</span></button><p class=\"lesson1-training-hint\">Tocca la scheda per vedere le forme dell'imperativo.</p></div></div></details>",
  "kurssLesson1": "            <h3>Lezione 1</h3>\n            <p class=\"kurss-lesson-intro\">Prima lezione: verbi al presente, vocaboli, pronuncia, grammatica e traduzione.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Verbi al presente</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">I verbi e la loro coniugazione al presente.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — venire</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>io vengo</span><span>du</span><strong>kommst</strong><span>tu vieni</span><span>er / sie</span><strong>kommt</strong><span>lui / lei viene</span><span>wir</span><strong>kommen</strong><span>noi veniamo</span><span>ihr</span><strong>kommt</strong><span>voi venite</span><span>sie / Sie</span><strong>kommen</strong><span>loro vengono / Lei viene</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — andare</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>io vado</span><span>du</span><strong>gehst</strong><span>tu vai</span><span>er / sie</span><strong>geht</strong><span>lui / lei va</span><span>wir</span><strong>gehen</strong><span>noi andiamo</span><span>ihr</span><strong>geht</strong><span>voi andate</span><span>sie / Sie</span><strong>gehen</strong><span>loro vanno / Lei va</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — stare in piedi</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>io sto in piedi</span><span>du</span><strong>stehst</strong><span>tu stai in piedi</span><span>er / sie</span><strong>steht</strong><span>lui / lei sta in piedi</span><span>wir</span><strong>stehen</strong><span>noi stiamo in piedi</span><span>ihr</span><strong>steht</strong><span>voi state in piedi</span><span>sie / Sie</span><strong>stehen</strong><span>loro stanno in piedi / Lei sta in piedi</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — cantare</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>io canto</span><span>du</span><strong>singst</strong><span>tu canti</span><span>er / sie</span><strong>singt</strong><span>lui / lei canta</span><span>wir</span><strong>singen</strong><span>noi cantiamo</span><span>ihr</span><strong>singt</strong><span>voi cantate</span><span>sie / Sie</span><strong>singen</strong><span>loro cantano / Lei canta</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Esempi</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Vocaboli</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>La pronuncia approssimativa delle parole è indicata tra parentesi con lettere italiane.<br>Tienine conto anche nelle lezioni successive.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (viir) — noi</div><div class=\"kurss-example\">Nella parola «wir» la lettera i si pronuncia lunga.</div><div class=\"kurss-example\">kommen (kommen) — venire</div><div class=\"kurss-example\">gehen (ghee-en) — andare</div><div class=\"kurss-example\">stehen (shtee-en) — stare in piedi</div><div class=\"kurss-example\">singen (singhen) — cantare</div><div class=\"kurss-example\">du (duu) kommst — tu vieni</div><div class=\"kurss-example\">er (eer) kommt — lui viene</div><div class=\"kurss-example\">sie (sii) kommt — lei viene</div><div class=\"kurss-example\">wer (veer) — chi?</div><div class=\"kurss-example\">ja (iaa) — sì</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronuncia</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">La pronuncia corretta delle parole, scritta con lettere italiane, è indicata nelle lezioni.</div><div class=\"kurss-example\">Wir (viir) — noi. In wir la i si pronuncia sempre lunga.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinito</h4><div class=\"lesson1-grammar-note\">La forma base del verbo. Di solito l'infinito termina in -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Desinenze del presente</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Togli <span class=\"lesson1-ending-accent\">-en</span> dalla forma base del verbo e aggiungi la desinenza.</strong></p><p>Esempio: kommen → komm + desinenza</p><div class=\"lesson1-ending-process\" aria-label=\"Come si formano le desinenze del presente\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>forma base</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>togli <span class=\"lesson1-ending-accent\">-en</span></strong><span>resta la radice</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>radice</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>aggiungi la desinenza</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Esempi</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Frasi interrogative</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Nella frase interrogativa tedesca il verbo di solito si sposta al primo posto.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In italiano:<br>Tu vieni.<br>Tu vieni?</div><div class=\"kurss-example\">In tedesco:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — tu vieni<br>kommst du? — vieni?</div><div class=\"kurss-example\">er singt — lui canta<br>singt er? — canta lui?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Differenza di persona</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — lui viene</div><div class=\"kurss-example\">sie kommt — lei viene</div><div class=\"kurss-example\">sie kommen — loro vengono</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traduci</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lezione 1: scheda di allenamento\">\n                    <span class=\"lesson1-training-progress\">Lezione 1 · Traduci: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Vieni?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Clicca sulla scheda per vedere la traduzione tedesca. Dopo la risposta, il clic successivo mostra la scheda seguente.</p>\n                </div>\n              </div>\n            </details>"
};

